#!/usr/bin/env python3
import sys
import os
import re
import argparse
import select
import termios
import tty

def is_binary(filepath):
    try:
        with open(filepath, 'rb') as f:
            chunk = f.read(1024)
            if b'\0' in chunk: return True
    except Exception: return True
    return False

class State:
    def __init__(self):
        self.search_query = ""
        self.replace_query = ""
        self.search_mode = 0 # 0: Simple, 1: Match Case, 2: Match Whole Word, 3: Match Case Whole Word, 4: Regex
        self.replace_mode = 0 # 0: Simple, 1: Preserve Case, 2: Delete Line
        self.active_pane = 0 # 0: Search, 1: Replace, 2: ResultList, 3: Preview
        self.files = []
        self.selected_file = 0
        self.selected_match = 0
        self.help_open = False
        self.help_tab = 0 # 0: Global, 1: Navigation
        self.project_root = "."

def do_search(state):
    if not state.search_query:
        state.files = []
        return

    flags = 0
    if state.search_mode == 0:
        flags = re.IGNORECASE
        pattern = re.escape(state.search_query)
    elif state.search_mode == 1:
        pattern = re.escape(state.search_query)
    elif state.search_mode == 2:
        flags = re.IGNORECASE
        pattern = r'\b' + re.escape(state.search_query) + r'\b'
    elif state.search_mode == 3:
        pattern = r'\b' + re.escape(state.search_query) + r'\b'
    elif state.search_mode == 4:
        pattern = state.search_query

    try:
        regex = re.compile(pattern, flags)
    except re.error:
        state.files = []
        return

    files = []
    for root, dirs, fnames in os.walk(state.project_root):
        dirs[:] = [d for d in dirs if not d.startswith('.')]
        for fname in fnames:
            if fname.startswith('.'): continue
            path = os.path.join(root, fname)
            if os.path.islink(path): continue
            if is_binary(path): continue

            try:
                with open(path, 'r', encoding='utf-8') as f:
                    lines = f.read().splitlines()
            except Exception:
                continue

            file_matches = []
            for i, line in enumerate(lines):
                for m in regex.finditer(line):
                    file_matches.append({
                        'line_idx': i,
                        'line': line,
                        'start': m.start(),
                        'end': m.end()
                    })
            if file_matches:
                files.append({
                    'path': path,
                    'rel_path': os.path.relpath(path, state.project_root),
                    'matches': file_matches,
                    'lines': lines
                })

    state.files = files
    if state.selected_file >= len(state.files):
        state.selected_file = max(0, len(state.files) - 1)

def get_blocks(file_obj):
    if not file_obj or not file_obj['matches']: return []
    match_lines = {}
    for m in file_obj['matches']:
        idx = m['line_idx']
        if idx not in match_lines:
            match_lines[idx] = []
        match_lines[idx].append(m)

    line_indices = sorted(match_lines.keys())
    blocks = []
    total_lines = len(file_obj['lines'])

    for i, idx in enumerate(line_indices):
        prev_idx = line_indices[i-1] if i > 0 else -1
        next_idx = line_indices[i+1] if i + 1 < len(line_indices) else total_lines

        start = max(idx - 3, prev_idx + 1 if prev_idx != -1 else 0)
        end = min(idx + 3, next_idx - 1 if next_idx != total_lines else total_lines - 1)

        blocks.append({
            'start': start,
            'end': end,
            'match_idx': idx,
            'matches_on_line': match_lines[idx]
        })
    return blocks

def _replace_in_file_logic(state, file_idx, match_idx_to_replace=None):
    if not state.files or file_idx >= len(state.files): return
    f_obj = state.files[file_idx]
    path = f_obj['path']
    lines = f_obj['lines']

    with open(path, 'w', encoding='utf-8') as f:
        to_replace = {}
        for m in f_obj['matches']:
            if match_idx_to_replace is None or m['line_idx'] == match_idx_to_replace:
                to_replace.setdefault(m['line_idx'], []).append(m)

        for i, line in enumerate(lines):
            if i in to_replace:
                if state.replace_mode == 2:
                    continue
                else:
                    new_line = line
                    for m in reversed(to_replace[i]):
                        s, e = m['start'], m['end']
                        repl = state.replace_query
                        if state.replace_mode == 1:
                            m_str = new_line[s:e]
                            if m_str.isupper(): repl = repl.upper()
                            elif m_str.islower(): repl = repl.lower()
                            elif m_str.istitle(): repl = repl.title()
                            else: repl = repl.lower()
                        new_line = new_line[:s] + repl + new_line[e:]
                    f.write(new_line + "\n")
            else:
                f.write(line + "\n")

def replace_in_file(state, file_idx, match_idx_to_replace=None):
    if not state.files: return
    old_path = state.files[file_idx]['path']
    _replace_in_file_logic(state, file_idx, match_idx_to_replace)
    do_search(state)
    for i, new_f in enumerate(state.files):
        if new_f['path'] == old_path:
            state.selected_file = i
            break
    else:
        if state.selected_file >= len(state.files):
            state.selected_file = max(0, len(state.files) - 1)
        if state.active_pane == 3:
            state.active_pane = 2

def replace_all(state):
    for i in range(len(state.files)):
        _replace_in_file_logic(state, i)
    do_search(state)
    state.selected_file = 0
    if state.active_pane == 3:
        state.active_pane = 2

def delete_from_process(state):
    if not state.files: return
    if state.active_pane == 2:
        del state.files[state.selected_file]
        if state.selected_file >= len(state.files):
            state.selected_file = max(0, len(state.files) - 1)
    elif state.active_pane == 3:
        f_obj = state.files[state.selected_file]
        blocks = get_blocks(f_obj)
        if not blocks: return
        match_idx = blocks[state.selected_match]['match_idx']
        f_obj['matches'] = [m for m in f_obj['matches'] if m['line_idx'] != match_idx]
        if not f_obj['matches']:
            del state.files[state.selected_file]
            if state.selected_file >= len(state.files):
                state.selected_file = max(0, len(state.files) - 1)
            state.active_pane = 2
        else:
            new_blocks = get_blocks(f_obj)
            if state.selected_match >= len(new_blocks):
                state.selected_match = max(0, len(new_blocks) - 1)

def write_at(y, x, s):
    sys.stdout.write(f"\033[{y};{x}H{s}")

def get_search_mode_str(mode):
    return ["Simple", "Match Case", "Match Whole Word", "Match Case Whole Word", "Regex"][mode]

def get_replace_mode_str(mode):
    return ["Simple", "Preserve Case", "Delete Line"][mode]

def truncate(s, max_len):
    if len(s) > max_len: return s[:max_len]
    return s

def draw_box(y, x, h, w, title, is_active):
    color = "\033[1m\033[38;5;2m" if is_active else "\033[38;5;15m"
    tl = f"{color}╭{title}"
    rem = w - 2 - len(title)
    if rem > 0: tl += "─" * rem
    tl += f"╮\033[0m"
    write_at(y, x, tl)

    for i in range(1, h - 1):
        write_at(y+i, x, f"{color}│\033[0m")
        write_at(y+i, x+w-1, f"{color}│\033[0m")

    bl = f"{color}╰" + "─"*(w - 2) + f"╯\033[0m"
    write_at(y+h-1, x, bl)

def draw_screen(state):
    try:
        cols, rows = os.get_terminal_size()
    except:
        cols, rows = 120, 30

    sys.stdout.write("\033[2J\033[H\033[?25l")

    left_w = int(cols * 0.3)
    right_w = cols - left_w

    s_title = f"Search" + "─"*(left_w - 2 - 6 - len(f"[{get_search_mode_str(state.search_mode)}]")) + f"[{get_search_mode_str(state.search_mode)}]"
    r_title = f"Replace" + "─"*(left_w - 2 - 7 - len(f"[{get_replace_mode_str(state.replace_mode)}]")) + f"[{get_replace_mode_str(state.replace_mode)}]"
    rl_title = "Result List"

    draw_box(1, 1, 3, left_w, s_title, state.active_pane == 0)
    write_at(2, 2, truncate(state.search_query, left_w-3))

    draw_box(4, 1, 3, left_w, r_title, state.active_pane == 1)
    if state.replace_mode == 2:
        write_at(5, 2, "\033[38;5;8m[Entire line will be deleted]\033[0m")
    else:
        write_at(5, 2, truncate(state.replace_query, left_w-3))

    draw_box(7, 1, rows - 7, left_w, rl_title, state.active_pane == 2)

    for i, f_obj in enumerate(state.files):
        if 7 + 1 + i >= rows - 1: break
        fname = f_obj['rel_path']
        if fname.startswith('./'): fname = fname[2:]
        count = len(f_obj['matches'])
        text = f"{fname} ({count})"
        text = truncate(text, left_w - 3)
        if i == state.selected_file:
            write_at(8+i, 2, f"\033[48;5;4m{text}\033[0m")
        else:
            write_at(8+i, 2, text)

    p_title = "Preview"
    draw_box(1, left_w + 1, rows - 1, right_w, p_title, state.active_pane == 3)

    if state.files:
        f_obj = state.files[state.selected_file]
        blocks = get_blocks(f_obj)
        y = 2
        for i, b in enumerate(blocks):
            if y >= rows - 1: break
            is_selected = (state.active_pane == 3 and state.selected_match == i)
            for line_idx in range(b['start'], b['end'] + 1):
                if y >= rows - 1: break
                line_text = f_obj['lines'][line_idx]
                prefix = "> " if is_selected and line_idx == b['match_idx'] else "  "
                write_at(y, left_w + 2, "")
                if is_selected and line_idx == b['match_idx']:
                    sys.stdout.write(f"\033[1m\033[38;5;15m{prefix}\033[0m")
                else:
                    sys.stdout.write(prefix)

                color_num = "\033[38;5;10m" if line_idx == b['match_idx'] else "\033[38;5;4m"
                sys.stdout.write(f"{color_num}{line_idx+1:4d} \033[0m")

                max_txt_len = right_w - 9
                if len(line_text) > max_txt_len:
                    line_text = line_text[:max_txt_len]

                if line_idx == b['match_idx']:
                    last_end = 0
                    for m in b['matches_on_line']:
                        s, e = m['start'], m['end']
                        if s > max_txt_len: s = max_txt_len
                        if e > max_txt_len: e = max_txt_len

                        sys.stdout.write(line_text[last_end:s])
                        if state.replace_mode == 2:
                            sys.stdout.write(f"\033[9m\033[38;5;15m\033[48;5;1m{line_text[s:e]}\033[0m")
                        elif state.replace_query:
                            repl = state.replace_query
                            if state.replace_mode == 1:
                                m_str = line_text[s:e]
                                if m_str.isupper(): repl = repl.upper()
                                elif m_str.islower(): repl = repl.lower()
                                elif m_str.istitle(): repl = repl.title()
                                else: repl = repl.lower()
                            sys.stdout.write(f"\033[9m\033[38;5;15m\033[48;5;9m{line_text[s:e]}\033[0m\033[38;5;15m\033[48;5;2m{repl}\033[0m")
                        else:
                            sys.stdout.write(f"\033[38;5;15m\033[48;5;4m{line_text[s:e]}\033[0m")
                        last_end = e
                    sys.stdout.write(line_text[last_end:])
                else:
                    sys.stdout.write(f"\033[38;5;8m{line_text}\033[0m")
                y += 1

            if y < rows - 1 and i < len(blocks) - 1:
                write_at(y, left_w + 2, "  \033[38;5;8m" + "-"*(right_w - 4) + "\033[0m")
                y += 1

    write_at(rows, 1, "\033[38;5;4m")
    if state.active_pane == 0:
        sys.stdout.write("Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>")
    elif state.active_pane == 1:
        sys.stdout.write("Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>")
    elif state.active_pane == 2:
        sys.stdout.write("Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k>")
    elif state.active_pane == 3:
        sys.stdout.write("Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k>")
    sys.stdout.write("\033[0m")

    if state.help_open:
        hy, hx = 5, int(cols*0.1)
        hw = int(cols*0.8)
        hh = 15
        for i in range(hh):
            write_at(hy+i, hx, " "*hw)
        color = "\033[38;5;3m"
        tl = f"{color}╭\033[38;5;2m [1] Global \033[38;5;3m─ [2] Navigation ───────────────────────────────Press 'q' to close╮\033[0m"
        write_at(hy, hx, tl)
        for i in range(1, hh - 1):
            write_at(hy+i, hx, f"{color}│\033[0m")
            write_at(hy+i, hx+hw-1, f"{color}│\033[0m")
        bl = f"{color}╰" + "─"*(hw - 2) + f"╯\033[0m"
        write_at(hy+hh-1, hx, bl)

        texts = [
            "- Ctrl-c: Quit",
            "- Ctrl-d: Quit",
            "- Ctrl-b: Help dialog",
            "- Ctrl-o: Process Replace For All Files",
            "- Ctrl-n: Loop through search and replace modes",
            "- Enter: Select/Deselect file",
            "- d: delete file/delete line from the replace process",
            "- r: Replace Selected File Or Line"
        ]
        for i, t in enumerate(texts):
            write_at(hy+i+2, hx+2, t)

    sys.stdout.flush()

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-p', '--project-root', default=".", help="Path to the project root")
    parser.add_argument('-h', '--help', action='store_true', help="Print help")
    parser.add_argument('-V', '--version', action='store_true', help="Print version")

    if "-V" in sys.argv or "--version" in sys.argv:
        config_dir = os.path.join(os.path.expanduser("~"), ".config", "serpl")
        print(f"serpl 0.3.4- (2026-04-20)\n\nAuthors: Yassine Bridi <ybridi@gmail.com>\n\nConfig directory: {config_dir}")
        sys.exit(0)

    args, unknown = parser.parse_known_args()

    if args.help:
        print("A simple terminal UI for search and replace, ala VS Code\n\nUsage: executable [OPTIONS]\n\nOptions:\n  -p, --project-root <PATH>  Path to the project root [default: .]\n  -h, --help                 Print help\n  -V, --version              Print version")
        sys.exit(0)

    state = State()
    state.project_root = args.project_root

    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    try:
        tty.setraw(fd)
        while True:
            draw_screen(state)
            if select.select([sys.stdin], [], [], 0.1)[0]:
                c = sys.stdin.read(1)

                if c == '\x1b':
                    if select.select([sys.stdin], [], [], 0.01)[0]:
                        seq = sys.stdin.read(2)
                        if seq == '[A': c = 'UP'
                        elif seq == '[B': c = 'DOWN'
                        elif seq == '[C': c = 'RIGHT'
                        elif seq == '[D': c = 'LEFT'
                        elif seq == '[Z': c = 'SHIFT_TAB'
                    else:
                        c = 'ESC'

                if state.help_open:
                    if c in ('q', 'ESC'):
                        state.help_open = False
                    continue

                if c in ('\x03', '\x04'):
                    break
                elif c == '\x02':
                    state.help_open = True
                elif c == '\t':
                    state.active_pane = (state.active_pane + 1) % 4
                elif c == 'SHIFT_TAB':
                    state.active_pane = (state.active_pane - 1) % 4
                elif c == '\x0e':
                    if state.active_pane == 0:
                        state.search_mode = (state.search_mode + 1) % 5
                    elif state.active_pane == 1:
                        state.replace_mode = (state.replace_mode + 1) % 3
                elif c == '\x0f':
                    replace_all(state)
                elif c in ('\r', '\n'):
                    if state.active_pane in (0, 1):
                        do_search(state)
                    elif state.active_pane == 2:
                        if state.files:
                            state.active_pane = 3
                            state.selected_match = 0
                    elif state.active_pane == 3:
                        state.active_pane = 2
                elif c == 'UP' or c == 'k':
                    if state.active_pane == 2 and state.selected_file > 0:
                        state.selected_file -= 1
                    elif state.active_pane == 3 and state.selected_match > 0:
                        state.selected_match -= 1
                elif c == 'DOWN' or c == 'j':
                    if state.active_pane == 2 and state.selected_file < len(state.files) - 1:
                        state.selected_file += 1
                    elif state.active_pane == 3 and state.files:
                        blocks = get_blocks(state.files[state.selected_file])
                        if state.selected_match < len(blocks) - 1:
                            state.selected_match += 1
                elif c == 'r':
                    if state.active_pane == 2:
                        replace_in_file(state, state.selected_file)
                    elif state.active_pane == 3:
                        blocks = get_blocks(state.files[state.selected_file])
                        if blocks:
                            replace_in_file(state, state.selected_file, blocks[state.selected_match]['match_idx'])
                elif c == 'd':
                    delete_from_process(state)
                elif c in ('\x7f', '\x08'):
                    if state.active_pane == 0:
                        state.search_query = state.search_query[:-1]
                    elif state.active_pane == 1:
                        state.replace_query = state.replace_query[:-1]
                else:
                    if len(c) == 1 and c.isprintable():
                        if state.active_pane == 0:
                            state.search_query += c
                        elif state.active_pane == 1:
                            state.replace_query += c

    finally:
        sys.stdout.write("\033[?25h\033[2J\033[H")
        termios.tcsetattr(fd, termios.TCSADRAIN, old)

if __name__ == "__main__":
    main()
