    if args.help:
        print("A simple terminal UI for search and replace, ala VS Code\n\nUsage: executable [OPTIONS]\n\nOptions:\n  -p, --project-root <PATH>  Path to the project root [default: .]\n  -h, --help                 Print help\n  -V, --version              Print version")
