    parser.add_argument('-h', '--help', action='store_true', help="Print help")
    parser.add_argument('-V', '--version', action='store_true', help="Print version")

    if "-V" in sys.argv or "--version" in sys.argv:
        config_dir = os.path.join(os.path.expanduser("~"), ".config", "serpl")
        print(f"serpl 0.3.4- (2026-04-20)\n\nAuthors: Yassine Bridi <ybridi@gmail.com>\n\nConfig directory: {config_dir}")
        sys.exit(0)

    args, unknown = parser.parse_known_args()

    if args.help:
        print("A simple terminal UI for search and replace, ala VS Code\n\nUsage: executable [OPTIONS]\n\nOptions:\n  -p, --project-root <PATH>  Path to the project root [default: .]\n  -h, --help                 Print help\n  -V, --version              Print version")
        sys.exit(0)

    state = State()
    state.project_root = args.project_root

    fd = sys.stdin.fileno()
    old = termios.tcgetattr(fd)
    try:
        tty.setraw(fd)
        while True:
            draw_screen(state)
            if select.select([sys.stdin], [], [], 0.1)[0]:
                c = sys.stdin.read(1)

                if c == '\x1b':
                    if select.select([sys.stdin], [], [], 0.01)[0]:
                        seq = sys.stdin.read(2)
                        if seq == '[A': c = 'UP'
                        elif seq == '[B': c = 'DOWN'
                        elif seq == '[C': c = 'RIGHT'
                        elif seq == '[D': c = 'LEFT'
                        elif seq == '[Z': c = 'SHIFT_TAB'
                    else:
                        c = 'ESC'

                if state.help_open:
                    if c in ('q', 'ESC'):
                        state.help_open = False
                    continue

                if c in ('\x03', '\x04'):
                    break
                elif c == '\x02':
                    state.help_open = True
                elif c == '\t':
                    state.active_pane = (state.active_pane + 1) % 4
                elif c == 'SHIFT_TAB':
                    state.active_pane = (state.active_pane - 1) % 4
                elif c == '\x0e':
                    if state.active_pane == 0:
                        state.search_mode = (state.search_mode + 1) % 5
                    elif state.active_pane == 1:
                        state.replace_mode = (state.replace_mode + 1) % 3
                elif c == '\x0f':
                    replace_all(state)
                elif c in ('\r', '\n'):
                    if state.active_pane in (0, 1):
                        do_search(state)
                    elif state.active_pane == 2:
                        if state.files:
                            state.active_pane = 3
                            state.selected_match = 0
                    elif state.active_pane == 3:
                        state.active_pane = 2
                elif c == 'UP':
                    if state.active_pane == 2 and state.selected_file > 0:
                        state.selected_file -= 1
                    elif state.active_pane == 3 and state.selected_match > 0:
                        state.selected_match -= 1
                elif c == 'DOWN':
                    if state.active_pane == 2 and state.files and state.selected_file < len(state.files) - 1:
                        state.selected_file += 1
                    elif state.active_pane == 3 and state.files:
                        blocks = get_blocks(state.files[state.selected_file])
                        if state.selected_match < len(blocks) - 1:
                            state.selected_match += 1
                elif c in ('\x7f', '\x08'):
                    if state.active_pane == 0:
                        state.search_query = state.search_query[:-1]
                    elif state.active_pane == 1:
                        state.replace_query = state.replace_query[:-1]
                else:
                    if state.active_pane in (2, 3):
                        if c == 'k':
                            if state.active_pane == 2 and state.selected_file > 0:
                                state.selected_file -= 1
                            elif state.active_pane == 3 and state.selected_match > 0:
                                state.selected_match -= 1
                        elif c == 'j':
                            if state.active_pane == 2 and state.files and state.selected_file < len(state.files) - 1:
                                state.selected_file += 1
                            elif state.active_pane == 3 and state.files:
                                blocks = get_blocks(state.files[state.selected_file])
                                if state.selected_match < len(blocks) - 1:
                                    state.selected_match += 1
                        elif c == 'r':
                            if state.active_pane == 2:
                                replace_in_file(state, state.selected_file)
                            elif state.active_pane == 3:
                                blocks = get_blocks(state.files[state.selected_file])
                                if blocks:
                                    replace_in_file(state, state.selected_file, blocks[state.selected_match]['match_idx'])
                        elif c == 'd':
                            delete_from_process(state)

                    if state.active_pane in (0, 1):
                        if len(c) == 1 and c.isprintable():
                            if state.active_pane == 0:
                                state.search_query += c
                            elif state.active_pane == 1:
                                state.replace_query += c

    except Exception as e:
        sys.stdout.write("\033[?25h\033[2J\033[H")
        termios.tcsetattr(fd, termios.TCSADRAIN, old)
        print("serpl error: Something went wrong")
        print("Error: ")
        print(f"   0: \033[91m{str(e)}\033[0m")
        sys.exit(1)
    finally:
        sys.stdout.write("\033[?25h\033[2J\033[H")
        termios.tcsetattr(fd, termios.TCSADRAIN, old)

if __name__ == "__main__":
    main()
