                            sys.stdout.write(f"\033[9m\033[38;5;15m\033[48;5;9m{line_text[s:e]}\033[0m\033[38;5;15m\033[48;5;2m{repl}\033[0m")
                        else:
                            sys.stdout.write(f"\033[38;5;15m\033[48;5;4m{line_text[s:e]}\033[0m")
                        last_end = e
                    sys.stdout.write(line_text[last_end:])
                else:
                    sys.stdout.write(f"\033[38;5;8m{line_text}\033[0m")
                y += 1

            if y < rows - 1 and i < len(blocks) - 1:
                write_at(y, left_w + 2, "  \033[38;5;8m" + "-"*(right_w - 4) + "\033[0m")
                y += 1

    write_at(rows, 1, "\033[38;5;4m")
    if state.active_pane == 0:
        sys.stdout.write("Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>")
    elif state.active_pane == 1:
        sys.stdout.write("Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>")
    elif state.active_pane == 2:
        sys.stdout.write("Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k>")
    elif state.active_pane == 3:
        sys.stdout.write("Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k>")
    sys.stdout.write("\033[0m")

    if state.help_open:
        hy, hx = 5, int(cols*0.1)
        hw = int(cols*0.8)
        hh = 15
        for i in range(hh):
            write_at(hy+i, hx, " "*hw)
        color = "\033[38;5;3m"
        tl = f"{color}╭\033[38;5;2m [1] Global \033[38;5;3m─ [2] Navigation ───────────────────────────────Press 'q' to close╮\033[0m"
        write_at(hy, hx, tl)
        for i in range(1, hh - 1):
            write_at(hy+i, hx, f"{color}│\033[0m")
            write_at(hy+i, hx+hw-1, f"{color}│\033[0m")
        bl = f"{color}╰" + "─"*(hw - 2) + f"╯\033[0m"
        write_at(hy+hh-1, hx, bl)

        texts = [
            "- Ctrl-c: Quit",
            "- Ctrl-d: Quit",
            "- Ctrl-b: Help dialog",
            "- Ctrl-o: Process Replace For All Files",
            "- Ctrl-n: Loop through search and replace modes",
            "- Enter: Select/Deselect file",
            "- d: delete file/delete line from the replace process",
            "- r: Replace Selected File Or Line"
        ]
        for i, t in enumerate(texts):
            write_at(hy+i+2, hx+2, t)

    if state.active_pane == 0:
        write_at(2, 2 + state.search_cursor, "")
        sys.stdout.write("\033[?25h")
    elif state.active_pane == 1 and state.replace_mode != 2:
        write_at(5, 2 + state.replace_cursor, "")
        sys.stdout.write("\033[?25h")
    else:
        sys.stdout.write("\033[?25l")
    sys.stdout.flush()

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('-p', '--project-root', default=".", help="Path to the project root")
    parser.add_argument('-h', '--help', action='store_true', help="Print help")
    parser.add_argument('-V', '--version', action='store_true', help="Print version")

    if "-V" in sys.argv or "--version" in sys.argv:
        config_dir = os.path.join(os.path.expanduser("~"), ".config", "serpl")
        print(f"serpl 0.3.4- (2026-04-20)\n\nAuthors: Yassine Bridi <ybridi@gmail.com>\n\nConfig directory: {config_dir}")
        sys.exit(0)

    args, unknown = parser.parse_known_args()

    if args.help:
        print("A simple terminal UI for search and replace, ala VS Code\n\nUsage: executable [OPTIONS]\n\nOptions:\n  -p, --project-root <PATH>  Path to the project root [default: .]\n  -h, --help                 Print help\n  -V, --version              Print version")
        sys.exit(0)

    state = State()
    state.project_root = args.project_root

    try:
        fd = sys.stdin.fileno()
        old = termios.tcgetattr(fd)
    except Exception as e:
        print("serpl error: Something went wrong\nError: \n   0: \033[91mResource temporarily unavailable (os error 11)\033[0m")
        sys.exit(1)

    try:
        tty.setraw(fd)
        while True:
            draw_screen(state)
            if select.select([sys.stdin], [], [], 0.05)[0]:
                seq = ""
                while select.select([sys.stdin], [], [], 0.01)[0]:
                    seq += sys.stdin.read(1)
                    if len(seq) > 10: break

                c = ""
                if seq == '\x1b':
                    c = 'ESC'
                elif seq.startswith('\x1b'):
                    if seq.endswith('A'): c = 'UP'
                    elif seq.endswith('B'): c = 'DOWN'
                    elif seq.endswith('C'): c = 'RIGHT'
                    elif seq.endswith('D'): c = 'LEFT'
                    elif seq.endswith('Z'): c = 'SHIFT_TAB'
                    else: c = 'ESC'
                else:
                    c = seq

                if state.help_open:
                    if c in ('q', 'ESC'):
                        state.help_open = False
                    continue

                if c in ('\x03', '\x04'):
                    break
                elif c == '\x02':
                    state.help_open = True
                elif c == '\t':
                    state.active_pane = (state.active_pane + 1) % 4
                elif c == 'SHIFT_TAB':
                    state.active_pane = (state.active_pane - 1) % 4
                elif c == '\x0e':
                    if state.active_pane == 0:
                        state.search_mode = (state.search_mode + 1) % 5
                    elif state.active_pane == 1:
                        state.replace_mode = (state.replace_mode + 1) % 3
                elif c == '\x0f':
                    replace_all(state)
                elif c in ('\r', '\n'):
                    if state.active_pane in (0, 1):
                        do_search(state)
                    elif state.active_pane == 2:
                        if state.files:
                            state.active_pane = 3
                            state.selected_match = 0
                    elif state.active_pane == 3:
                        state.active_pane = 2
                elif c == 'UP':
                    if state.active_pane == 2 and state.selected_file > 0:
                        state.selected_file -= 1
                    elif state.active_pane == 3 and state.selected_match > 0:
                        state.selected_match -= 1
                elif c == 'DOWN':
                    if state.active_pane == 2 and state.files and state.selected_file < len(state.files) - 1:
                        state.selected_file += 1
                    elif state.active_pane == 3 and state.files:
                        blocks = get_blocks(state.files[state.selected_file])
                        if state.selected_match < len(blocks) - 1:
                            state.selected_match += 1
                elif c == 'LEFT':
                    if state.active_pane == 0 and state.search_cursor > 0:
                        state.search_cursor -= 1
                    elif state.active_pane == 1 and state.replace_cursor > 0:
                        state.replace_cursor -= 1
                elif c == 'RIGHT':
                    if state.active_pane == 0 and state.search_cursor < len(state.search_query):
                        state.search_cursor += 1
                    elif state.active_pane == 1 and state.replace_cursor < len(state.replace_query):
                        state.replace_cursor += 1
                elif c in ('\x7f', '\x08'):
                    if state.active_pane == 0 and state.search_cursor > 0:
                        state.search_query = state.search_query[:state.search_cursor-1] + state.search_query[state.search_cursor:]
                        state.search_cursor -= 1
                    elif state.active_pane == 1 and state.replace_cursor > 0:
                        state.replace_query = state.replace_query[:state.replace_cursor-1] + state.replace_query[state.replace_cursor:]
                        state.replace_cursor -= 1
                else:
                    if state.active_pane in (2, 3):
                        if c == 'k':
                            if state.active_pane == 2 and state.selected_file > 0:
                                state.selected_file -= 1
                            elif state.active_pane == 3 and state.selected_match > 0:
                                state.selected_match -= 1
                        elif c == 'j':
                            if state.active_pane == 2 and state.files and state.selected_file < len(state.files) - 1:
                                state.selected_file += 1
                            elif state.active_pane == 3 and state.files:
                                blocks = get_blocks(state.files[state.selected_file])
                                if state.selected_match < len(blocks) - 1:
                                    state.selected_match += 1
                        elif c == 'r':
                            if state.active_pane == 2:
                                replace_in_file(state, state.selected_file)
                            elif state.active_pane == 3:
                                blocks = get_blocks(state.files[state.selected_file])
                                if blocks:
                                    replace_in_file(state, state.selected_file, blocks[state.selected_match]['match_idx'])
                        elif c == 'd':
                            delete_from_process(state)

                    if state.active_pane in (0, 1):
                        for char in c:
                            if len(char) == 1 and char.isprintable():
                                if state.active_pane == 0:
                                    state.search_query = state.search_query[:state.search_cursor] + char + state.search_query[state.search_cursor:]
                                    state.search_cursor += 1
                                elif state.active_pane == 1:
                                    state.replace_query = state.replace_query[:state.replace_cursor] + char + state.replace_query[state.replace_cursor:]
                                    state.replace_cursor += 1

    finally:
        sys.stdout.write("\033[?25h\033[2J\033[H")
        try:
            termios.tcsetattr(fd, termios.TCSADRAIN, old)
        except Exception:
            pass

if __name__ == "__main__":
    main()
