content = content.replace(old_event_loop, new_event_loop)

# One more fix: If `sys.stdin.read(1)` is blocking, it will block `draw_screen`. I need `select` to just process input.
# The main issue with `[` was `seq.endswith('D')` didn't catch it if my loop was wrong. But by skipping `LEFT` in the `else` block, `for char in 'LEFT'` won't print!
# Actually, the problem was exactly that `for char in c:` was printing `LEFT`. But wait! I saw `[D` printed!
# This means `c` was NOT `LEFT`. `c` was `\x1b[D`.
# Why? Because my reading loop didn't catch `\x1b` properly!
# I will use a very robust reading loop:
old_read = """            if select.select([sys.stdin], [], [], 0.05)[0]:
                seq = ""
                while select.select([sys.stdin], [], [], 0.01)[0]:
                    seq += sys.stdin.read(1)
                    if len(seq) > 10: break

                c = ""
                if seq == '\\x1b':
                    c = 'ESC'
                elif seq.startswith('\\x1b'):
                    if seq.endswith('A'): c = 'UP'
                    elif seq.endswith('B'): c = 'DOWN'
                    elif seq.endswith('C'): c = 'RIGHT'
                    elif seq.endswith('D'): c = 'LEFT'
                    elif seq.endswith('Z'): c = 'SHIFT_TAB'
                    else: c = 'ESC'
                else:
                    c = seq"""

new_read = """            if select.select([sys.stdin], [], [], 0.05)[0]:
                c = sys.stdin.read(1)
                if c == '\\x1b':
                    if select.select([sys.stdin], [], [], 0.01)[0]:
                        seq = sys.stdin.read(1)
                        if seq == '[' or seq == 'O':
                            if select.select([sys.stdin], [], [], 0.01)[0]:
                                seq2 = sys.stdin.read(1)
                                if seq2 == 'A': c = 'UP'
                                elif seq2 == 'B': c = 'DOWN'
                                elif seq2 == 'C': c = 'RIGHT'
                                elif seq2 == 'D': c = 'LEFT'
                                elif seq2 == 'Z': c = 'SHIFT_TAB'
                                else: c = 'ESC'
                            else: c = 'ESC'
                        else: c = 'ESC'
                    else: c = 'ESC'"""

content = content.replace(old_read, new_read)

with open("src/main.py", "w") as f:
    f.write(content)
